<?php

namespace App\OpenApi;

use ApiPlatform\OpenApi\Factory\OpenApiFactoryInterface;
use ApiPlatform\OpenApi\Model\Operation;
use ApiPlatform\OpenApi\OpenApi;
use Symfony\Component\DependencyInjection\Attribute\AsDecorator;
use Symfony\Component\DependencyInjection\Attribute\AutowireDecorated;

/**
 * Completes the generated document: OpenAPI 3.1, the query, header and body parameters and the error responses.
 */
#[AsDecorator(decorates: 'api_platform.openapi.factory')]
final class JsonApiOpenApiFactory implements OpenApiFactoryInterface
{
    /** Pagination parameters generated by API Platform, replaced by page[number] and page[size]. */
    private const REPLACED_PARAMETERS = ['page'];

    private const ACCESSORS = [
        'get' => ['getGet', 'withGet'],
        'post' => ['getPost', 'withPost'],
        'patch' => ['getPatch', 'withPatch'],
    ];

    public function __construct(
        #[AutowireDecorated]
        private readonly OpenApiFactoryInterface $decorated,
    ) {
    }

    public function __invoke(array $context = []): OpenApi
    {
        $openApi = ($this->decorated)($context)->withOpenapi('3.1.0');
        $paths = $openApi->getPaths();

        foreach (ApiDocumentation::operations() as $path => $methods) {
            $pathItem = $paths->getPath($path);
            if (null === $pathItem) {
                continue;
            }
            foreach ($methods as $method => $documentation) {
                [$getter, $wither] = self::ACCESSORS[$method];
                $operation = $pathItem->{$getter}();
                if (null === $operation) {
                    continue;
                }
                $pathItem = $pathItem->{$wither}($this->document($operation, $documentation));
            }
            $paths->addPath($path, $pathItem);
        }

        return $openApi;
    }

    /**
     * @param array{summary: string, parameters?: list<object>, requestBody?: object, responses: array<string, object>} $documentation
     */
    private function document(Operation $operation, array $documentation): Operation
    {
        $parameters = array_values(array_filter(
            $operation->getParameters() ?? [],
            static fn (object $parameter): bool => !\in_array($parameter->getName(), self::REPLACED_PARAMETERS, true),
        ));
        $parameters = array_merge($parameters, $documentation['parameters'] ?? []);

        $operation = $operation
            ->withSummary($documentation['summary'])
            ->withParameters($parameters)
            ->withResponses($documentation['responses']);

        return isset($documentation['requestBody']) ? $operation->withRequestBody($documentation['requestBody']) : $operation;
    }
}
